import{_ as d,o as a,c as e,ag as r}from"./chunks/framework.C5oN-8Wt.js";const o="/cns_master_docs/teaching-v0.4.0-alpha/02-find-delay.svg",b=JSON.parse('{"title":"02 两段数据相差多久？","description":"","frontmatter":{},"headers":[],"relativePath":"v0.4.0-alpha/learn/02-find-delay/index.md","filePath":"v0.4.0-alpha/learn/02-find-delay/index.md"}'),s={name:"v0.4.0-alpha/learn/02-find-delay/index.md"};function l(n,t,h,p,c,i){return a(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="_02-两段数据相差多久" tabindex="-1">02 两段数据相差多久？ <a class="header-anchor" href="#_02-两段数据相差多久" aria-label="Permalink to &quot;02 两段数据相差多久？&quot;">​</a></h1><p>适用 CNS Master <strong>v0.4.0-alpha</strong>。先手算预测，再运行工程，对照结果。</p><h2 id="低空观测问题与学习目标" tabindex="-1">低空观测问题与学习目标 <a class="header-anchor" href="#低空观测问题与学习目标" aria-label="Permalink to &quot;低空观测问题与学习目标&quot;">​</a></h2><p>假设地面观测设备保存了一段已知的短信号，又收到一段形状相同、出现得更晚的数据。怎样判断它晚了几个采样点？本课先用 PC 点表和延时器构造这一问题，再用相关器逐个试移位。它帮助理解时间差的计算，不代表已经发现无人机或测到了真实回波。</p><p>完成本课后，应能读懂正负 lag，手算一处相关值，并区分“原始采样率”“一帧多少点”和“每秒多少相关帧”。本课只从相关图手工读峰；下一课再加入自动找峰的模块。</p><h2 id="先备知识-数点、乘法与加法" tabindex="-1">先备知识：数点、乘法与加法 <a class="header-anchor" href="#先备知识-数点、乘法与加法" aria-label="Permalink to &quot;先备知识：数点、乘法与加法&quot;">​</a></h2><p>一条数字信号可以先理解成按顺序排列的一串数。采样率 Fs=1000 sample/s 表示每秒取 1000 个数，相邻样本间隔是 <code>1/1000=0.001 s</code>，即 1 ms。若同一形状晚 2 个点出现，时间差就是 2 ms。这里的幅度数值不表示米或秒。</p><p>“先把对应位置相乘，再把结果相加”叫作乘加。本例只需算 <code>1×1+2×2+1×1=6</code>，不需要先学习傅里叶变换。相关器把这个动作放在许多相对移位上，帮助寻找对齐处。移位量记作 lag，单位是 sample。</p><h2 id="打开本课工程" tabindex="-1">打开本课工程 <a class="header-anchor" href="#打开本课工程" aria-label="Permalink to &quot;打开本课工程&quot;">​</a></h2><p><a href="../../../downloads/teaching-v0.4.0-alpha/02-find-delay.cnsproj" download>下载 02-find-delay.cnsproj</a></p><p>在程序中用“文件 → 打开工程”（<strong>Ctrl+O</strong>）选择下载文件。工程已保存参考／延时波形的叠加观察器，以及相关帧的单路观察器。打开只恢复配置；准备并运行后，再读取本次数据。</p><h2 id="接线与选择理由" tabindex="-1">接线与选择理由 <a class="header-anchor" href="#接线与选择理由" aria-label="Permalink to &quot;接线与选择理由&quot;">​</a></h2><p>箭头表示数值流，观察器只读取输出：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>向量点表源（实标量）────────→ 相关器 ref</span></span>
<span class="line"><span>                    └→ 延时器 → 相关器 rx</span></span>
<span class="line"><span>                              │ correlation</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                        观察器：单路 lag 图</span></span></code></pre></div><p>同一个源分成两路，让两路的原始采样率一致。直接支路作参考，延时支路作待比较数据；交换 <code>rx</code>、<code>ref</code> 会改变 lag 的正负含义。两路都是实标量流，不把整张八点表打包成一个八分量 item。</p><p>本课设置原始 Fs=1000 sample/s、相关帧长 <code>frame_length=8</code>、延时 2 个标量样本，源循环下面的八点表。三个非零点后留五个零，使延时 2 或 3 点后，短序列仍完整留在各自的八点窗口里。</p><table tabindex="0"><thead><tr><th>帧内样本下标 n</th><th>ref：循环点表</th><th>rx：延时 2 点</th><th>对照 rx：延时 3 点</th></tr></thead><tbody><tr><td>0</td><td>1</td><td>0</td><td>0</td></tr><tr><td>1</td><td>2</td><td>0</td><td>0</td></tr><tr><td>2</td><td>1</td><td>1</td><td>0</td></tr><tr><td>3</td><td>0</td><td>2</td><td>1</td></tr><tr><td>4</td><td>0</td><td>1</td><td>2</td></tr><tr><td>5</td><td>0</td><td>0</td><td>1</td></tr><tr><td>6</td><td>0</td><td>0</td><td>0</td></tr><tr><td>7</td><td>0</td><td>0</td><td>0</td></tr></tbody></table><p>这张表表示本课构造的完整输入窗，不是传感器采集记录。模块虽然叫“向量点表源”，本课仍选择<strong>实数 float32</strong>、<code>vlen=1</code>：每次输出一个数，按表中顺序循环；不是每次输出一个八分量向量。实部表填写 <code>[1,2,1,0,0,0,0,0]</code>，虚部表填写八个 0。</p><h2 id="本课设置与操作" tabindex="-1">本课设置与操作 <a class="header-anchor" href="#本课设置与操作" aria-label="Permalink to &quot;本课设置与操作&quot;">​</a></h2><ol><li>建立上图。点表源设 <code>sample_rate_hz=1000</code>、实数 float32、<code>vlen=1</code>，填写上述实部与虚部表；延时器也选实数 float32、<code>vlen=1</code>，将 <code>delay_samples</code> 设为 2。</li><li>将相关器“非重叠窗口点数 N”设为 8。图底部“参考源样本数”填 <strong>64</strong>。本图只有一个 1000 Hz 的源，因此两个相关输入各得到 Q=64 个标量样本，形成 <code>64/8=8</code> 个完整窗；64 不是相关输出帧数。</li><li>准备后运行。用波形观察器查看点表源和延时器的输出，核对两路的完整输入窗；若与上表不同，先查源、延时和窗口边界，不从相关峰倒猜输入。</li><li>另开一个观察器，捕获相关器 <code>correlation</code> 的<strong>完整父向量</strong>，不要选某个分量。单路显示为“相关值—滞后”，横轴为 −7 至 +7 sample，纵轴为相关值；它显示最新一个完整帧，不是时间波形。</li><li>等本轮任务完成，记录峰位置、峰值、帧长及真实原始 Fs。只改下面指定的一项，重新准备并运行，再比较两轮完整帧。</li></ol><h2 id="预期图像-把-2-的位置算出来" tabindex="-1">预期图像：把 +2 的位置算出来 <a class="header-anchor" href="#预期图像-把-2-的位置算出来" aria-label="Permalink to &quot;预期图像：把 +2 的位置算出来&quot;">​</a></h2><p>相关器采用 full 原始互相关，即计算所有相对移位：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C[k] = Σ rx[n+k] × ref[n]</span></span>
<span class="line"><span>k = −(N−1), …, 0, …, +(N−1)</span></span></code></pre></div><p>求和遍历参考窗内的 n；窗口外参与计算的值按零处理。这是相关公式的数学定义，不表示运行时会补齐不足一帧的输入。<strong>正 lag 表示 rx 相对 ref 延迟。</strong></p><p>在 k=+2 时，rx 中的 <code>1、2、1</code> 与 ref 中的 <code>1、2、1</code> 对齐，因此 <code>C[2]=1×1+2×2+1×1=6</code>。在 k=+1 时，只得到 <code>1×2+2×1=4</code>。全部 15 个值应为：</p><table tabindex="0"><thead><tr><th>lag / sample</th><th>−7</th><th>−6</th><th>−5</th><th>−4</th><th>−3</th><th>−2</th><th>−1</th><th>0</th><th>+1</th><th>+2</th><th>+3</th><th>+4</th><th>+5</th><th>+6</th><th>+7</th></tr></thead><tbody><tr><td>理论 C[k]</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td><td>1</td><td>4</td><td>6</td><td>4</td><td>1</td><td>0</td><td>0</td><td>0</td></tr></tbody></table><p>在相关图上，非零部分从 lag=0 到 +4 依次为 <code>1、4、6、4、1</code>，最高点位于 +2，其余位置为零。唯一最大绝对值在 lag=+2，相关值为 +6。原始相关不去均值、不归一化，也不自动除以 N；6 不是“600% 的相似度”，不能把纵轴限制成 −1 到 +1 后再解释。</p><p>每个相关输出 item 含 <code>2N−1=15</code> 个分量，代表同一帧的 15 个 lag。它们不是连续 15 个时刻。原始 Fs=1000、N=8 时，相关 item 率为 <code>1000/8=125 item/s</code>，帧时刻是输入窗口起点。算 2 点对应的延迟仍用 <code>2/1000</code>，不能用 <code>2/125</code>。</p><p>本轮应得到 8 个完整相关帧，每帧包含表中的 15 项相关值。先从图中找到最高点，再用数表核对它的 lag 和相关值。本课由你手动读峰，下一课再接入峰值检测器。</p><h2 id="单参数对照-只把延时-2-点改成-3-点" tabindex="-1">单参数对照：只把延时 2 点改成 3 点 <a class="header-anchor" href="#单参数对照-只把延时-2-点改成-3-点" aria-label="Permalink to &quot;单参数对照：只把延时 2 点改成 3 点&quot;">​</a></h2><p>保持点表、Fs、N、Q 及所有观察设置不变，只把延时器的延时样本数从 2 改成 3，重新准备并运行。rx 完整帧已列在上表；非零部分从下标 2—4 移到 3—5，没有跨窗。</p><p>相关图的非零部分应整体向右移一格，峰从 +2 移到 +3，峰值仍为 +6，对应延迟从 0.002 s 变为 0.003 s。先预测，再用本次输入和相关输出逐项核对。</p><p>对照下图，延时从 2 点改为 3 点后，输入向右移动一格，相关峰也从 +2 移到 +3，峰值保持为 6。</p><p><img src="`+o+'" alt="延时 2 点和 3 点的输入及相关结果"></p><h2 id="常见问题与模型边界" tabindex="-1">常见问题与模型边界 <a class="header-anchor" href="#常见问题与模型边界" aria-label="Permalink to &quot;常见问题与模型边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>应如何理解或检查</th></tr></thead><tbody><tr><td>参考和接收支路接反后出现负 lag</td><td>正负由 <code>rx/ref</code> 的顺序定义。负 lag 表示 rx 更早，不能取绝对值掩盖接线问题。</td></tr><tr><td>把 rx 反号，峰会变成负数吗？</td><td>本例应仍在 +2，相关值变为 −6。最大绝对值用来找位置，输出保留相关值符号；负相关不等于负距离。反号是另一个概念说明，不混入本课单参数对照。</td></tr><tr><td>全零或常数输入能不能送入相关器？</td><td>相关器仍输出真实数学结果，不伪造峰。若后接峰值检测器，静默、并列绝对峰或最大绝对值不高于阈值，会使任务失败。</td></tr><tr><td>有限点数不是 N 的整数倍</td><td>准备时报出节点、Q 与 N，要求调整。不会补尾，也不会用半帧报告成功。N 的允许范围是整数 8—512。</td></tr><tr><td>相关图不能切换到频谱或多路 XY</td><td>相关父向量只按单路 lag 域显示。需要比较两轮时，记录各轮的真实完整帧。</td></tr><tr><td>能否把这张表一直重复，当作连续目标探测？</td><td>本例只为保证帧内完整而构造。周期重复、真实回波截断和跨窗会产生歧义；唯一算术峰不证明存在真实目标，也不代表检测置信度。</td></tr></tbody></table><p>本课的相关器可以保留全零或常量输入的真实结果。下一课加入峰值检测器后，还会检查唯一峰与阈值；届时屏幕留有旧点不代表新一帧成功，也不能将缺失结果补成零。</p><p><a href="./../../modules/correlator/">相关器参考</a> · <a href="./../../modules/peak_detector/">峰值检测器参考</a> · <a href="./../03-delay-to-distance/">下一课：延迟怎样换成距离 →</a> · <a href="./../">返回学习路径</a></p>',38)])])}const m=d(s,[["render",l]]);export{b as __pageData,m as default};
